            for(int col = 0; col < field.getWidth(); col++) {
                for (PopulationRule rule : POPULATION_RULES) {
                    if (rule.tryPopulate(rand, field, row, col, animals, plants)) {
                        break;
                    }
                }
            }
        }
    }

